    r = pypdf.PdfReader(path)
    return "\n".join(page.extract_text() or "" for page in r.pages)

def read_docx(path):
    d = docx.Document(path)
    out = [p.text for p in d.paragraphs if p.text.strip()]
    for t in d.tables:
        for row in t.rows:
